contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides deposit amount and a minsum and log address
    // We record initial on-chain and contract-observed balances, perform Deposit via receive or Deposit(),
    // then assert that the recorded balance increased by exactly the deposited amount.
    function runTest(uint amt, uint minsum, address logfile) public payable {
        // preconditions: provide enough ETH to send and non-zero amount to observe change
        require(amt > 0);
        require(msg.value == amt);

        // ensure contract is configurable before initialization
        c.SetMinSum(minsum);
        c.SetLogFile(logfile);
        // record initial stored balance for this test contract
        uint beforeRecorded = c.balances(address(this));
        uint beforeEth = address(c).balance;

        // perform deposit by sending ETH to c which triggers receive() -> Deposit()
        // send the ETH to c
        (bool ok,) = address(c).call{value: amt}("\x00");
        require(ok);

        // observe after values
        uint afterRecorded = c.balances(address(this));
        uint afterEth = address(c).balance;

        // assert that the contract's stored balance for this caller increased exactly by amt
        assert(afterRecorded - beforeRecorded == amt && afterEth - beforeEth == amt);
    }

    // Allow contract to receive ETH so it can forward to c
    receive() external payable {}
}

