pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, address collector, uint256 depositAmt, uint256 collectAmt) public {
        // keep addresses non-zero and distinct wide domain
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));
        // give depositors some ETH to deposit
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // set MinSum low and finalize initialization so Collect may proceed if balances suffice
        c.SetMinSum(0);
        c.Initialized();

        // fund depositor and have them deposit via Deposit()
        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // record balances snapshot for a few addresses including depositor and collector
        uint256 bal_depositor_before = c.balances(depositor);
        uint256 bal_collector_before = c.balances(collector);
        uint256 bal_contract_before = address(c).balance;

        // attempt Collect from collector for the fuzzed collectAmt
        bool ok;
        vm.prank(collector);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // After Collect returns (succeeded or not), read balances again
        uint256 bal_depositor_after = c.balances(depositor);
        uint256 bal_collector_after = c.balances(collector);
        uint256 bal_contract_after = address(c).balance;

        // General rule: For the correct contract, Collect should never increase any address's recorded balance
        // compared to before Collect; check this for depositor and collector and contract balance.
        // This single assertTrue encodes the universal property: neither tracked balances nor the contract
        // balance increased as a result of Collect. The mutant that corrupted Deposit can cause an
        // increase in some address's recorded balance, violating this.
        assertTrue(bal_depositor_after <= bal_depositor_before && bal_collector_after <= bal_collector_before && bal_contract_after <= bal_contract_before);
    }
}

