pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: depositor address, deposit amount, collect amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // Keep depositor non-zero
        vm.assume(depositor != address(0));
        // keep amounts reasonable and non-zero where needed
        depositAmt = bound(depositAmt, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 0, type(uint128).max);

        // Ensure MinSum is small so Collect can be allowed; set before Initialized()
        c.SetMinSum(1);
        c.Initialized();

        // Fund depositor externally so they can send depositAmt
        vm.deal(depositor, depositAmt);

        // Make depositor deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Pre-Collect balance snapshot for depositor (from contract getter)
        uint256 before = c.balances(depositor);

        // Ensure collectAmt is <= before and before >= MinSum to make Collect permitted
        // If not permitted, don't assert the property (we only care about permitted case)
        if (!(before >= 1 && before >= collectAmt)) {
            // Nothing to assert for this input; return early
            return;
        }

        // Caller performs Collect
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // If Collect reverted, the reference would not revert in permitted case; however
        // Collect can only revert if the external transfer fails (msg.sender.call), which
        // for an EOA succeeds. So on the reference contract ok should be true. If the
        // mutant changes balances via malformed deposits, Collect may still succeed but
        // balances will differ. We assert the universal property: after a successful
        // Collect, recorded balance decreased exactly by collectAmt.
        if (ok) {
            uint256 after = c.balances(depositor);
            assertTrue(after + collectAmt == before);
        }
    }
}

